function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -10 || v > 10)) return 'Each value is an integer between -10 and 10.';
  if (nums.some(v => v === 0)) return 'No value of nums may be 0.';
  return null;
}

