function returnToBoundaryCount(nums) {
  let count = 0;
  for (let end = 0; end < nums.length; end++) {
    let right = 0, left = 0;
    for (let k = 0; k <= end; k++) {
      if (nums[k] > 0) right += nums[k];
      else left += -nums[k];
    }
    if (right === left) count++;
  }
  return count;
}

