function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  // Small magnitudes make returns to the boundary common; large inputs use the full range.
  const span = size === 'large' ? (rand() < 0.5 ? 10 : 3) : 1 + Math.floor(rand() * 3);
  const nums = [];
  for (let i = 0; i < n; i++) {
    const magnitude = 1 + Math.floor(rand() * span);
    nums.push(rand() < 0.5 ? -magnitude : magnitude);
  }
  return [nums];
}
